    ["note_drop_ifstats_dynamic"] = "Drops estão disponíveis na interface principal",
    ["note_drops_sflow"] = "Os drops são mostradas apenas para o sFlow, pois o NetFlow não as reporta.<br><A HREF=https://www.ietf.org/rfc/rfc3176.txt>sFlow</A> drops contam o número de vezes que o agente sFlow detectou que um pacote marcado para ser amostrado foi descartado devido à falta de recursos. O contador de drops informa o número total de drops detectadas desde a última reinicialização do agente. Uma taxa de queda alta indica que o agente de gerenciamento não pode processar amostras tão rápido quanto elas estão sendo geradas pelo hardware. Aumentar a taxa de amostragem do sFlow reduzirá a taxa de queda. Nota: Um agente que não pode detectar quedas informará sempre zero.",
    ["note_lifetime_timeout"] = "Independentemente da duração do fluxo, um fluxo que esteja ativo por mais que o <A HREF=https://www.ntop.org/guides/nprobe/cli_options.html?highlight=maximum%20flow%20lifetime>lifetime</A> máximo especificado é considerado expirado e será emitido (opção nProbe -t)",
    ["note_packets"] = "Em redes ethernet, cada pacote tem um <A HREF=\"https://en.wikipedia.org/wiki/Ethernet_frame\">sobrecarga de 24 bytes</A> [preamble (7 bytes), início do quadro (1 byte), CRC (4 bytes), e <A HREF=\"http://en.wikipedia.org/wiki/Interframe_gap\">IFG</A> (12 bytes)].Essa sobrecarga precisa ser contabilizada no tráfego da interface, mas não é adicionada ao tráfego que está sendo trocado entre os endereços IP. Isso ocorre porque esses dados contribuem para o carregamento da interface, mas não podem ser contabilizados no tráfego que está sendo trocado pelos hosts e, portanto, esperam poucas discrepâncias entre os valores de tráfego do host e da interface..",
    ["note_probe_zmq_drops_export_queue_full"] = "O probe remoto processou com êxito esses fluxos, mas não conseguiu enfileirá-los para a exportação, pois a fila de exportação estava cheia.",
