    ["dynamic_interfaces_creation_description"] = "O ntopng pode usar um critério para desagregar o tráfego de entrada. Quando um critério de desagregação é selecionado, o ntopng usará o valor de critério para desviar o tráfego de entrada para interfaces criadas dinamicamente. Por exemplo, quando o critério 'VLAN Id' é selecionado, uma interface dinâmica será criada para cada ID de VLAN observada, e o tráfego de entrada será desviado para uma interface dinâmica, dependendo do valor de ID da VLAN. ",
