    ["toggle_src_with_post_nat_src_description"] = "Substituir endereços de origem IPv4 (%%IPV4_SRC_ADDR) e portas (%%L4_SRC_PORT) com seus valores pós-nat (%%POST_NAT_SRC_IPV4_ADDR and %%POST_NAT_SRC_TRANSPORT_PORT).",
    ["toggle_src_with_post_nat_src_title"] = "Use Endereços e Portas IPv4 de Origem Pós-Nat",
