    ["toggle_tiny_flows_dump_description"] = "Alterna a exportação de fluxos pequenos, que são fluxos com poucos pacotes ou bytes. Reduz a cardinalidade de fluxo em bancos de dados, acelera inserções e pesquisas. Ajustar fluxos minúsculos pode ajudar a limitar a cardinalidade do fluxo sem reduzir a visibilidade nas informações descartadas.",
    ["toggle_tiny_flows_dump_title"] = "Exportação de fluxos minúsculos",
    ["toggle_tls_quic_hostnaming_description"] = "Use o TLS/QUIC SNI solicitado como nome de host. Ativá-lo torna a nomeação de host mais eficaz, mas pode introduzir falsos positivos nos nomes de host.",
