    ["toggle_toggle_starttls_title"] = "Habilitar STARTTLS",
    ["toggle_top_sites_description"] = "Alterne a criação dos principais sites visitados para hosts locais. Os principais sites são criados usando um <a href=\"%{url}\">heuristic</a> que não mantêm mais de 20 sites por host local. A heurística opera totalmente na memória e não requer nenhuma interação com o disco. Os principais sites são apagados a cada 5 minutos. É possível criar um arquivo histórico dos principais sites visitados, para cada host local, consultando periodicamente o JSON <i class=\"fas fa-download fa-sm\"></i> link de download acessível a partir da página de detalhes do host.",
    ["toggle_top_sites_title"] = "Principais sites HTTP",
